loadRootEnv();

export default defineConfig({
  schema: 'prisma/schema.prisma',
  migrations: { path: 'prisma/migrations' },
  // Undefined is fine for `prisma generate`; migrate commands fail with a clear message.
  datasource: { url: process.env['DATABASE_URL'] },
});
// Prisma 7: connection URL lives in prisma.config.ts, not here.
generator client {
  provider = "prisma-client"
  output   = "../src/__generated__/prisma"
}

datasource db {
  provider = "postgresql"
}

// Mirrors the GraphQL `USState` enum (schema.graphql is the source of truth).
enum USState {
  AL
  AK
  AZ
  AR
  CA
  CO
  CT
  DE
