  await page.route('**/graphql', async (route) => { await gate; await route.continue(); });
  await page.goto('http://127.0.0.1:5273/');
  const skel = page.getByRole('status', { name: 'Loading properties' });
  await skel.waitFor();
  await page.screenshot({ path: '.playwright-mcp/smoke-skeleton.png' });
  await page.setViewportSize({ width: 390, height: 800 });
  await page.screenshot({ path: '.playwright-mcp/smoke-skeleton-390.png' });
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth);
  await page.setViewportSize({ width: 1200, height: 850 });
  release();
  await page.unroute('**/graphql');
  await skel.waitFor({ state: 'detached' });
  return { overflowAt390: overflow };
}

