     1	import os from 'node:os';
     2	
     3	const R = '[REDACTED]';
     4	
     5	// Value character class that stops at quotes, whitespace, `&` and backslashes, so replacing
     6	// inside JSON-escaped text (raw .jsonl lines) never consumes an escape and never breaks the JSON.
     7	const VALUE = String.raw`[^\s"'&\\]+`;
     8	
     9	/** Ordered [pattern, replacement] rules. Applied to raw JSONL lines and rendered Markdown alike. */
    10	export const RULES = [
    11	  // Weatherstack puts the key in the query string.
    12	  [new RegExp(String.raw`(access_key=[REDACTED]\[REDACTED)${VALUE}`, 'gi'), `$1${R}`],
    13	  // KEY=[REDACTED] / SECRET=[REDACTED] / TOKEN=[REDACTED] / PASSWORD=[REDACTED] (env files, shell exports).
    14	  [
    15	    new RegExp(
    16	      String.raw`\b([A-Z0-9_]*(?:KEY|SECRET|TOKEN|PASSWORD|PASSWD)[A-Z0-9_]*)=(?!\[REDACTED)${VALUE}`,
    17	      'g',
    18	    ),
    19	    `$1=${R}`,
    20	  ],
    21	  [/(Bearer\s+)(?!\[REDACTED)[A-Za-z0-9._~+/=-]{8,}/g, `$1${R}`],
    22	  [/\bsk-ant-[A-Za-z0-9_-]{10,}/g, R],
    23	  [/\b(?:ghp|gho|ghs|github_pat|sk|pk)_[A-Za-z0-9_]{16,}/g, R],
    24	  // Credentials inside connection strings: postgres://[REDACTED]@host -> postgres://[REDACTED]@host
    25	  [
    26	    /\b((?:postgres(?:ql)?|mysql|mongodb(?:\+srv)?|redis):\/\/)(?!\[REDACTED)[^\s:/@"\\]+:[^\s@"\\]+@/g,
    27	    `$1${R}@`,
    28	  ],
    29	  // Account identifiers recorded by Claude Code in transcript metadata.
    30	  [/("(?:organization|account|org)(?:Uuid|Id)"\s*:\s*")(?!\[REDACTED)[^"\\]+/gi, `$1${R}`],
    31	  [/[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}/g, '[REDACTED_EMAIL]'],
    32	];
    33	
    34	function homeRules() {
    35	  const home = os.homedir();
    36	  const user = os.userInfo().username;
    37	  const rules = [];
    38	  if (home && home !== '/') rules.push([new RegExp(escape(home), 'g'), '~']);
    39	  // Other absolute home dirs (e.g. transcripts recorded on another machine).
    40	  rules.push([/\/(?:Users|home)\/[^/\s"'\\]+/g, '~']);
    41	  // Claude Code encodes the project dir as -Users-<name>-Projects-...
    42	  if (user) rules.push([new RegExp(`-(?:Users|home)-${escape(user)}-`, 'g'), '-~-']);
    43	  return rules;
    44	}
    45	
    46	function escape(s) {
    47	  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    48	}
    49	
    50	export function redact(text) {
    51	  let out = text;
    52	  for (const [re, rep] of [...RULES, ...homeRules()]) out = out.replace(re, rep);
    53	  return out;
    54	}
    55	
    56	/** Patterns that must never survive redaction; used as a final assertion on written files. */
    57	const LEAKS = [
    58	  ['email', /[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}/],
    59	  ['access_key', /access_key=[REDACTED]\[REDACTED)[^\s"'&\\]/i],
    60	  [
    61	    'secret assignment',
    62	    /\b[A-Z0-9_]*(?:KEY|SECRET|TOKEN|PASSWORD)[A-Z0-9_]*=(?!\[REDACTED)[^\s"'&\\]/,
    63	  ],
    64	  ['anthropic key', /sk-ant-[A-Za-z0-9_-]{10,}/],
    65	  ['home path', /\/(?:Users|home)\/[^/\s"'\\~]/],
    66	];
    67	
    68	/** Returns a list of `{ kind, sample }` for anything that still looks sensitive. */
    69	export function findLeaks(text) {
    70	  const found = [];
