  [/("(?:organization|account|org)(?:Uuid|Id)"\s*:\s*")(?!\[REDACTED)[^"\\]+/gi, `$1${R}`],
  [/[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}/g, '[REDACTED_EMAIL]'],
];

