        Query: { fields: { properties: { merge: false } } },
        // Weather has no id: it is the creation-time snapshot owned by one Property. Merge the
        // list's and the detail view's selections instead of letting one overwrite the other.
        Weather: { merge: true },
      },
    }),
  });
}

